import { createHash } from 'node:crypto';
import {
    METADATA_LOOKUP_LIMITS, SAME_AS_RELEASE_CREDIT, type LookupArtistCredit, type LookupDate, type MusicBrainzRelease, type MusicBrainzReleaseSummary,
    type MusicBrainzTrack
} from './lookupContract';
import { decoratedNameParts } from './lookupDecoratedNames';
import { isPlaceholderCredit, normalizeGtin, normalizeItunesId, normalizeMusicBrainzId } from './lookupIdentifiers';
import {
    LOOKUP_EXPECTED_TRACKLIST_BOUNDS, expectedTracklistFromRelease, lookupAudioTrackCount, lookupDurationMs, lookupResolvedPairing, lookupSubsetPairing,
    lookupSubsetTrackCountPlausible, lookupUnpairableMembers, releaseAudioTracks, type LookupPairedBy, type LookupPositionHint, type LookupSubsetPair
} from './lookupSubset';
import { keepableMusicBrainzId } from '../../utils/musicBrainzId';

/**
 * Pure ranking of lookup candidates against the import's selected files, or in subset mode against an
 * existing Album's members. It never makes a request: calling it again with newly known durations or
 * numbers re-ranks the stored candidates. Matching candidates all score the same; those that would
 * write identical draft values form one group. The result is identical under any permutation of the
 * inputs. The only matching group is preselected only when the comparison is complete: a search that
 * offered more releases than were compared (`searchComplete: false`) or an incomplete candidate that
 * could match may hide another matching group, so the comparison is disclosed as partial and only an
 * embedded identifier still preselects. An iTunes-only candidate never shares a group with a
 * MusicBrainz one, and is preselected only when MusicBrainz answered without a release for it or
 * stayed unavailable (then flagged `notChecked`). In subset mode a pairing that is not single may
 * still resolve through the members' position hints or near-exact durations (lookupResolvedPairing),
 * recorded as the comparison's `pairedBy`.
 */
export type LocalFileEvidence = {
    slotId: string; order: number;
    durationMs: number | null;
    /** 0 for millisecond durations, 1000 for legacy `mm:ss` durations. */
    durationPrecisionMs: 0 | 1000;
    discNumber: number | null; trackNumber: number | null;
    artistTags: string[];
    identifiers: { releaseId: string | null; barcode: string | null; catalogNumber: string | null };
    /** An existing-Album review member's position hint (lookupReviewEvidence.ts); absent elsewhere and never an own number. */
    positionHint?: LookupPositionHint;
};
export type LookupCandidate = {
    /** For an iTunes-only candidate `releaseId` is its collection ID and `itunesCheck` why it was not checked against MusicBrainz. */
    key: string; source: 'musicbrainz' | 'itunes'; releaseId: string; itunesCheck?: 'noRelease' | 'unavailable' | 'notRun';
    summary: MusicBrainzReleaseSummary | null;
    /** Null when the release details could not be fetched: the candidate is incomplete. */
    release: MusicBrainzRelease | null;
    /** The release total a search reported for a release found without a summary (a recording hit); absent when unknown. */
    reportedTrackCount?: number | null;
    /** The release no longer exists (its lookup answered 404), so, though incomplete, it cannot match. */
    missing?: boolean;
};
/** The draft values a release would write; each Artist entry and the label carry the MusicBrainz ID it credits (null for none). */
export type LookupProposal = {
    albumTitle: string;
    artists: { name: string; role: 'primary' | 'featured'; joinPhrase: string | null; musicBrainzId: string | null }[];
    label: string | null;
    labelMusicBrainzId: string | null;
    releaseDate: LookupDate | null;
    tracks: { discNumber: number; trackNumber: number; title: string }[];
};
export type LookupMatchStatus = 'matching' | 'unverified' | 'notMatching' | 'incomplete';
export type LookupDifference = 'trackCount' | 'discCount' | 'duration';
/** Subset mode only: no single pairing exists, or the release offers no expected tracklist within its bounds. */
export type LookupSubsetDifference = 'pairing' | 'tooManyTracks' | 'tracklistInvalid';
export type LookupFileComparison = { slotId: string; localMs: number | null; candidateMs: number | null; deltaMs: number | null; withinTolerance: boolean | null };
/**
 * What a subset comparison found: tracks left out as video, data or pregap; the pairing (null when the track count or the
 * tracklist already rules the release out) and its pairs in member order; the release tracks no member pairs with (only for a
 * single pairing) and how many missing-file rows the release would add; and the members no audio track can pair with.
 * `pairedBy` says how a pairing that was not single became single (lookupResolvedPairing); absent otherwise, and stored only: the
 * lookup view does not project it.
 */
export type LookupSubsetComparison = {
    leftOutTracks: number; pairing: 'unique' | 'ambiguous' | 'none' | null; pairedBy?: LookupPairedBy; pairs: LookupSubsetPair[];
    missingTracks: { discNumber: number; trackNumber: number }[] | null; missingTrackCount: number | null; unpairableSlotIds: string[];
};
export type LookupComparison = {
    trackCount: { local: number; candidate: number };
    discCount: { local: number | null; candidate: number };
    files: LookupFileComparison[];
    differences: (LookupDifference | LookupSubsetDifference)[];
    unknownLocalDurations: number;
    unknownCandidateDurations: number;
    /** Present in subset mode only. */
    subset?: LookupSubsetComparison;
};
export type RankedLookupCandidate = {
    key: string; releaseId: string; status: LookupMatchStatus;
    comparison: LookupComparison | null; proposal: LookupProposal | null;
    groupKey: string | null; artistMismatch: boolean | null;
};
export type RankedLookupGroup = { groupKey: string; representativeKey: string; memberKeys: string[]; proposal: LookupProposal };
/**
 * `notChecked` (present only when true): an iTunes-only candidate preselected while MusicBrainz stayed unavailable.
 * `exactTrackCount` (subset mode only): the one matching group whose release has exactly as many audio tracks as members.
 */
export type LookupPreselection = { candidateKey: string; groupKey: string; basis: 'releaseId' | 'barcode' | 'catalogNumber' | 'onlyMatchingGroup' | 'exactTrackCount';
    artistMismatch: boolean; notChecked?: boolean };
export type RankedLookup = {
    candidates: RankedLookupCandidate[];
    groups: RankedLookupGroup[];
    preselection: LookupPreselection | null;
    /** `partialComparison`: not every release the searches offered was compared, so a lone matching group is not proof. */
    disclosure: { unknownLocalDurations: number; unknownLocalDiscNumbers: number; partialComparison: boolean };
    /**
     * Subset mode only. `exact`: no release left out of the comparison could have exactly as many tracks as members; `subset`: none
     * could have at least as many (the comparison is partial without it).
     */
    completeness?: { exact: boolean; subset: boolean };
};
/** The track Artist entries a paired member would get, or why none: no usable credit, or only placeholders and repeats. */
export type LookupTrackArtists = { artists: LookupProposal['artists'] } | { reason: 'missing' | 'placeholder' };
/** `exact` compares an import's files with every release track; `subset` lets a release have more tracks than an Album has members. */
export type LookupComparisonMode = 'exact' | 'subset';

/** A release whose reported track count is unknown (absent, not a positive integer) can still match; a known one must equal the file count. */
export const lookupTrackCountPlausible = (reported: unknown, fileCount: number): boolean =>
    !(Number.isSafeInteger(reported) && (reported as number) > 0) || reported === fileCount;

/** Legacy durations are stored rounded to whole seconds (`m:ss` or `h:mm:ss`). */
export const legacyDurationEvidence = (value: unknown): { durationMs: number; durationPrecisionMs: 1000 } | null => {
    const match = typeof value === 'string' && value.length <= 16 ? /^(?:(\d+):)?([0-5]?\d):([0-5]\d)$/.exec(value) : null;
    if (!match) return null;
    const durationMs = ((Number(match[1] ?? 0) * 60 + Number(match[2])) * 60 + Number(match[3])) * 1000;
    return durationMs > 0 && Number.isSafeInteger(durationMs) ? { durationMs, durationPrecisionMs: 1000 } : null;
};

const featuring = /(?:^|[\s(（])(?:feat\.?|ft\.?|featuring)(?=$|[\s.)）])/i;
const clean = (value: string) => value.normalize('NFC').trim();
const folded = (value: string) => clean(value).toLowerCase();

/**
 * The Artist entries of an artist credit: placeholders are never proposed, and a credit that repeats an earlier one's MusicBrainz
 * artist or folded name is dropped (only its first entry is kept). A dropped credit's join phrase is not moved, as with
 * placeholders: a byline ignores a trailing phrase. Each entry carries the MusicBrainz ID the credit names.
 */
export const lookupCreditEntries = (credits: readonly LookupArtistCredit[]): LookupProposal['artists'] => {
    let featured = false;
    const artists: LookupProposal['artists'] = [], seen = new Set<string>();
    for (const credit of credits) {
        const role = featured ? 'featured' as const : 'primary' as const;
        // The entry after a featuring phrase, and every later entry, is featured.
        if (featuring.test(credit.joinPhrase)) featured = true;
        if (isPlaceholderCredit(credit.name, credit.artistId) || isPlaceholderCredit(credit.artistName)) continue;
        const artistId = normalizeMusicBrainzId(credit.artistId), name = `name:${folded(credit.name)}`;
        if ((artistId && seen.has(`id:${artistId}`)) || seen.has(name)) continue;
        if (artistId) seen.add(`id:${artistId}`);
        seen.add(name);
        // Join phrases keep their surrounding spaces: they are part of the byline presentation.
        const joinPhrase = credit.joinPhrase.normalize('NFC');
        artists.push({ name: clean(credit.name), role, joinPhrase: joinPhrase ? joinPhrase : null, musicBrainzId: keepableMusicBrainzId(artistId) });
    }
    return artists;
};

/**
 * The draft values a release would write: the release credit's entries (lookupCreditEntries), so candidates that credit different
 * artists under one name are different proposals; a `[no label]` label is never proposed, and the label carries the MusicBrainz
 * ID the release credits. Track credits never enter it.
 */
export const proposalForRelease = (release: MusicBrainzRelease): LookupProposal => {
    const artists = lookupCreditEntries(release.artistCredit);
    const first = release.labels.find(label => label.name !== null || label.labelId !== null);
    const label = first?.name && !isPlaceholderCredit(first.name, first.labelId) ? clean(first.name) : null;
    return {
        albumTitle: clean(release.title), artists, label, labelMusicBrainzId: label === null ? null : keepableMusicBrainzId(first!.labelId),
        releaseDate: release.groupFirstReleaseDate ?? release.date,
        // Discs are numbered among the media that have tracks, as the disc-count comparison counts them,
        // so a CD after a DVD without a tracklist is Disc Number 1.
        tracks: release.media.filter(medium => medium.tracks.length).flatMap((medium, index) =>
            medium.tracks.map(track => ({ discNumber: index + 1, trackNumber: track.position, title: clean(track.title) })))
    };
};

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
/**
 * A release track's own artist credit: the stored marker reads as the release's credit. Null when the track has none (absent,
 * or stored before track credits were kept) or any entry is malformed, as in a stored shape from another release.
 */
export function lookupTrackCredit(release: Pick<MusicBrainzRelease, 'artistCredit'>, track: Pick<MusicBrainzTrack, 'artistCredit'>): LookupArtistCredit[] | null {
    const credit = isRecord(track) ? track.artistCredit === SAME_AS_RELEASE_CREDIT ? (isRecord(release) ? release.artistCredit : null) : track.artistCredit : null;
    return Array.isArray(credit) && credit.every(entry => isRecord(entry) && typeof entry.name === 'string' && typeof entry.joinPhrase === 'string'
        && typeof entry.artistId === 'string' && typeof entry.artistName === 'string') ? credit : null;
}

/**
 * The track Artist entries one release track proposes, from its own credit only (never the release's or an Album's), through the
 * same rules as the release's entries (lookupCreditEntries) but without entries whose name is empty: `missing` without a usable
 * credit, or when every entry's name is empty (an iTunes song may give an empty artist string); `placeholder` when no entry
 * remains.
 */
export function trackArtistProposal(release: Pick<MusicBrainzRelease, 'artistCredit'>, track: Pick<MusicBrainzTrack, 'artistCredit'>): LookupTrackArtists {
    const credit = lookupTrackCredit(release, track);
    if (!credit?.some(entry => clean(entry.name))) return { reason: 'missing' };
    const artists = lookupCreditEntries(credit).filter(artist => artist.name !== '');
    return artists.length ? { artists } : { reason: 'placeholder' };
}

const canonical = (value: unknown): string => {
    if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
    if (value && typeof value === 'object') return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
    return JSON.stringify(value);
};
/** MusicBrainz group keys hash the proposal alone, as before iTunes candidates existed; iTunes ones also name the source, so groups never mix sources. */
const groupKeyFor = (proposal: LookupProposal, source: LookupCandidate['source']) =>
    createHash('sha256').update(canonical(source === 'itunes' ? { source: 'itunes', proposal } : proposal)).digest('hex');
/**
 * Subset group keys hash the Album values of the proposal with the expected tracklist (durations included), the pairs and each
 * paired member's track Artist entries, so equal Album values with another pairing, other row durations or other paired track
 * credits are other groups. The proposal's own tracks are left out: a review writes member values from the rows and pairs, and
 * those tracks also list left-out video tracks, which would split a CD edition from its CD+DVD edition.
 */
const subsetGroupKeyFor = (proposal: LookupProposal, source: LookupCandidate['source'], group: ReturnType<typeof compareSubset>['group']) => {
    const { tracks: _tracks, ...albumValues } = proposal;
    return createHash('sha256').update(canonical({ comparison: 'subset', source, proposal: albumValues, ...group })).digest('hex');
};
const byText = (left: string, right: string) => left < right ? -1 : left > right ? 1 : 0;

/**
 * Deterministic file order: Disc Number (unknown counts as 1), Track Number (unknown last), then
 * upload order. When some Disc Numbers are unknown and Track Numbers repeat (numbering restarts
 * on every disc), disc membership cannot be inferred, so upload order alone decides.
 */
const orderedFiles = (files: readonly LocalFileEvidence[]) => {
    const tracks = files.map(file => file.trackNumber).filter((track): track is number => track !== null);
    const byUpload = files.some(file => file.discNumber === null) && new Set(tracks).size !== tracks.length;
    return [...files].sort((left, right) => (byUpload ? 0
        : (left.discNumber ?? 1) - (right.discNumber ?? 1)
        || (left.trackNumber ?? Number.POSITIVE_INFINITY) - (right.trackNumber ?? Number.POSITIVE_INFINITY))
        || left.order - right.order || byText(left.slotId, right.slotId));
};

/**
 * The candidate track each local file takes when the track counts agree: the ranking's file order paired with the proposal's
 * tracks in medium order (the flattening the comparison uses), with each track's Disc Number among the media that have tracks.
 * Null when the counts differ. Pure.
 */
export const lookupTrackAssignment = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[]):
    { slotId: string; discNumber: number; trackNumber: number; title: string }[] | null => {
    const tracks = proposalForRelease(release).tracks, ordered = orderedFiles(files);
    if (!ordered.length || tracks.length !== ordered.length) return null;
    return ordered.map((file, index) => ({ slotId: file.slotId, ...tracks[index] }));
};

/**
 * The expected-tracklist row and track Artist entries each member takes in a subset comparison, in the ranking's member order:
 * only when the release offers an expected tracklist (so at least one audio row) and the pairing is single, as
 * lookupResolvedPairing resolves it (lookupSubset.ts), so a choice writes what a current ranking paired; with `resolve` false, only
 * when the strict pairing is single (lookupSubsetPairing), for a candidate a stored ranking listed as pairing in more than one way
 * (chooseLookupCandidate). `[]` without members. Pure.
 */
export function lookupSubsetAssignment(release: MusicBrainzRelease, files: readonly LocalFileEvidence[], toleranceMs: number = METADATA_LOOKUP_LIMITS.durationToleranceMs,
    resolve = true): { slotId: string; discNumber: number; trackNumber: number; title: string; durationMs: number | null; artists: LookupTrackArtists }[] | null {
    const tracklist = expectedTracklistFromRelease(release);
    if (!('rows' in tracklist)) return null;
    const pairing = (resolve ? lookupResolvedPairing : lookupSubsetPairing)(tracklist.rows, orderedFiles(files), toleranceMs);
    if (pairing.kind !== 'unique') return null;
    const tracks = releaseAudioTracks(release).tracks, rowAt = new Map(tracklist.rows.map((row, index) => [`${row.discNumber}:${row.trackNumber}`, index]));
    return pairing.pairs.map(pair => {
        const index = rowAt.get(`${pair.discNumber}:${pair.trackNumber}`)!, row = tracklist.rows[index];
        return { slotId: pair.slotId, discNumber: row.discNumber, trackNumber: row.trackNumber, title: row.title, durationMs: row.durationMs,
            artists: trackArtistProposal(release, tracks[index].track) };
    });
}

const compareRelease = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[], toleranceMs: number) => {
    const tracks = release.media.flatMap(medium => medium.tracks);
    const counted = files.length === tracks.length;
    const localDiscs = files.length && files.every(file => file.discNumber !== null) ? new Set(files.map(file => file.discNumber)).size : null;
    const candidateDiscs = release.media.filter(medium => medium.tracks.length).length;
    const rows: LookupFileComparison[] = files.map((file, index) => {
        const candidateMs = counted ? tracks[index].lengthMs : null;
        const known = counted && file.durationMs !== null && candidateMs !== null;
        const deltaMs = known ? file.durationMs! - candidateMs! : null;
        return { slotId: file.slotId, localMs: file.durationMs, candidateMs, deltaMs,
            withinTolerance: deltaMs === null ? null : Math.abs(deltaMs) <= toleranceMs + file.durationPrecisionMs };
    });
    const differences: LookupDifference[] = [];
    if (!counted) differences.push('trackCount');
    if (localDiscs !== null && localDiscs !== candidateDiscs) differences.push('discCount');
    if (rows.some(row => row.withinTolerance === false)) differences.push('duration');
    const comparison: LookupComparison = {
        trackCount: { local: files.length, candidate: tracks.length },
        discCount: { local: localDiscs, candidate: candidateDiscs },
        files: rows, differences,
        unknownLocalDurations: files.filter(file => file.durationMs === null).length,
        unknownCandidateDurations: tracks.filter(track => track.lengthMs === null).length
    };
    const status: LookupMatchStatus = differences.length ? 'notMatching'
        : comparison.unknownLocalDurations || comparison.unknownCandidateDurations ? 'unverified' : 'matching';
    const order = [
        Math.abs(files.length - tracks.length),
        localDiscs === null ? 0 : Math.abs(localDiscs - candidateDiscs),
        counted ? rows.reduce((sum, row) => sum + Math.abs(row.deltaMs ?? 0), 0) : 0
    ];
    return { comparison, status, order };
};

/**
 * Subset comparison of one release with an existing Album's members (`files`, in ranking order): only audio tracks count, and the
 * release may have more tracks and discs than the Album has members. Fewer audio tracks than members (or none), or no expected
 * tracklist within its bounds, does not match; otherwise members pair with the rows (lookupSubset.ts): no pairing does not match,
 * several pairings that neither the members' position hints nor near-exact durations decide (lookupResolvedPairing), no members or
 * a member or paired row without a duration leave it unverified, and a single pairing with every duration known matches. How a
 * resolved pairing was decided (`pairedBy`) never enters the group key. A member duration that is not positive and finite is
 * unknown, and only a precision of 1000 widens the tolerance, as in pairing. `group` holds what a matching candidate's group key
 * adds to its proposal's Album values.
 */
const compareSubset = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[], toleranceMs: number) => {
    const audio = releaseAudioTracks(release), tracklist = expectedTracklistFromRelease(release), audioCount = audio.tracks.length;
    const rows = 'rows' in tracklist ? tracklist.rows : [];
    const localDiscs = files.length && files.every(file => file.discNumber !== null) ? new Set(files.map(file => file.discNumber)).size : null;
    const differences: (LookupDifference | LookupSubsetDifference)[] = [];
    if (audioCount < files.length) differences.push('trackCount');
    // A release without audio tracks offers no tracklist for the same reason (`trackCount`), which is listed once.
    if ('reason' in tracklist && !differences.includes(tracklist.reason)) differences.push(tracklist.reason);
    const pairing = differences.length ? null : lookupResolvedPairing(rows, files, toleranceMs);
    if (pairing?.kind === 'none') differences.push('pairing');
    const pairs = pairing?.kind === 'unique' ? pairing.pairs : null;
    const rowAt = new Map(rows.map((row, index) => [`${row.discNumber}:${row.trackNumber}`, index]));
    // Pairs follow the members' order, so a member's pair is at its own index.
    const pairedRows = pairs?.map(pair => rowAt.get(`${pair.discNumber}:${pair.trackNumber}`)!) ?? null;
    const fileRows: LookupFileComparison[] = files.map((file, index) => {
        const localMs = lookupDurationMs(file.durationMs), candidateMs = pairedRows ? rows[pairedRows[index]].durationMs : null;
        const deltaMs = localMs !== null && candidateMs !== null ? localMs - candidateMs : null, precision = file.durationPrecisionMs === 1000 ? 1000 : 0;
        return { slotId: file.slotId, localMs, candidateMs, deltaMs, withinTolerance: deltaMs === null ? null : Math.abs(deltaMs) <= toleranceMs + precision };
    });
    const paired = new Set(pairedRows ?? []);
    const comparison: LookupComparison = {
        trackCount: { local: files.length, candidate: audioCount },
        discCount: { local: localDiscs, candidate: audio.discCount },
        files: fileRows, differences,
        unknownLocalDurations: fileRows.filter(row => row.localMs === null).length,
        unknownCandidateDurations: audio.tracks.filter(track => track.durationMs === null).length,
        subset: {
            leftOutTracks: audio.leftOutTracks, pairing: pairing?.kind ?? null,
            ...(pairing?.kind === 'unique' && pairing.pairedBy ? { pairedBy: pairing.pairedBy } : {}), pairs: pairs ?? [],
            missingTracks: pairedRows ? rows.filter((_row, index) => !paired.has(index)).map(row => ({ discNumber: row.discNumber, trackNumber: row.trackNumber })) : null,
            missingTrackCount: 'rows' in tracklist && audioCount >= files.length ? audioCount - files.length : null,
            // Bounded like the tracklist, so a box set's tracks are not paired member by member.
            unpairableSlotIds: audioCount <= LOOKUP_EXPECTED_TRACKLIST_BOUNDS.rows ? lookupUnpairableMembers(audio.tracks, files, toleranceMs) : []
        }
    };
    const status: LookupMatchStatus = differences.length ? 'notMatching'
        : !pairedRows || !files.length || fileRows.some(row => row.deltaMs === null) ? 'unverified' : 'matching';
    const order = [audioCount < files.length ? 1 : 0, Math.abs(audioCount - files.length), fileRows.reduce((sum, row) => sum + Math.abs(row.deltaMs ?? 0), 0)];
    const byMember = (left: readonly [string, ...unknown[]], right: readonly [string, ...unknown[]]) => byText(left[0], right[0]);
    const group = {
        rows,
        pairs: (pairs ?? []).map(pair => [pair.slotId, pair.discNumber, pair.trackNumber] as [string, number, number]).sort(byMember),
        tracks: (pairs ?? []).map((pair, index) => [pair.slotId, trackArtistProposal(release, audio.tracks[pairedRows![index]].track)] as [string, LookupTrackArtists]).sort(byMember)
    };
    return { comparison, status, order, audioCount, group };
};

/**
 * True when artist tags exist and none, nor either part of a decorated one (lookupDecoratedNames.ts), equals the joined credit, a
 * credited name, a canonical artist name, an alias the lookup found for a credited artist (`aliases`, by MusicBrainz ID) or another
 * name of an iTunes localized name group (`localized`) that holds one of those names. Only the tag side is read for parts.
 */
const artistMismatchFor = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[], aliases?: ReadonlyMap<string, readonly string[]>,
    localized?: readonly (readonly string[])[]) => {
    const tags = new Set(files.flatMap(file => file.artistTags).filter((tag): tag is string => typeof tag === 'string')
        .flatMap(tag => [tag, ...(decoratedNameParts(tag) ?? [])]).map(folded).filter(Boolean));
    if (!tags.size) return false;
    const names = new Set([
        folded(release.artistCredit.map(credit => credit.name + credit.joinPhrase).join('')),
        ...release.artistCredit.flatMap(credit => [folded(credit.name), folded(credit.artistName),
            ...(aliases?.get(normalizeMusicBrainzId(credit.artistId) ?? '') ?? []).filter(name => typeof name === 'string').map(folded)])
    ]);
    const groups = (Array.isArray(localized) ? localized : []).map(group => (Array.isArray(group) ? group : []).filter((name): name is string => typeof name === 'string').map(folded));
    for (const group of groups.filter(group => group.some(name => names.has(name)))) for (const name of group) names.add(name);
    return ![...tags].some(tag => names.has(tag));
};

/** An identifier counts only when every file carries the same valid value. */
const sharedIdentifier = (files: readonly LocalFileEvidence[], read: (file: LocalFileEvidence) => string | null) => {
    const values = new Set(files.map(read));
    const [value] = values;
    return files.length && values.size === 1 && value ? value : null;
};

/**
 * A fetched release counts only when it is the candidate's own release (by MusicBrainz ID, or for an iTunes-only candidate by its
 * collection ID); otherwise the candidate is incomplete.
 */
const usableRelease = (candidate: LookupCandidate) => !candidate.release ? null
    : candidate.source === 'itunes' ? normalizeItunesId(candidate.releaseId) !== null && candidate.release.releaseId === candidate.releaseId ? candidate.release : null
        : normalizeMusicBrainzId(candidate.releaseId) !== null && normalizeMusicBrainzId(candidate.release.releaseId) === normalizeMusicBrainzId(candidate.releaseId) ? candidate.release : null;

/** Duplicate keys keep the most complete entry, chosen without regard to input order. */
const distinctCandidates = (candidates: readonly LookupCandidate[]) => {
    const chosen = new Map<string, LookupCandidate>();
    const weight = (candidate: LookupCandidate) => (usableRelease(candidate) ? 2 : 0) + (candidate.summary ? 1 : 0);
    for (const candidate of candidates) {
        const current = chosen.get(candidate.key);
        if (!current || weight(candidate) > weight(current)
            || (weight(candidate) === weight(current) && canonical(candidate) < canonical(current))) chosen.set(candidate.key, candidate);
    }
    return [...chosen.values()];
};

/**
 * `searchComplete` false marks a comparison partial; left out, the searches count as complete (pure callers and tests). An
 * incomplete candidate makes it partial too, unless it cannot match: it no longer exists or reported another track count.
 * `aliases` are the artist aliases the run found, by MusicBrainz ID, and `localized` its iTunes localized name groups
 * (artistMismatchFor). An iTunes-only candidate is preselectable only when its check is `noRelease` or `unavailable`: an
 * identifier that names one that is not preselects nothing, and neither does an only matching group it represents.
 *
 * `comparison: 'subset'` compares an existing Album's members (`files`) with each release's audio tracks (compareSubset) and adds
 * `subset` to each comparison and `completeness` to the result; the default `exact` comparison is unchanged. In subset mode an
 * incomplete candidate that could have at least as many audio tracks as members makes the comparison partial, and one that could
 * have exactly as many breaks `completeness.exact`, as does `exactSearchComplete: false` (a search that left out such a release;
 * it defaults to `searchComplete`). After the identifier rules, while `completeness.exact` holds, the one matching group whose
 * release has exactly as many audio tracks as members is preselected (`exactTrackCount`) even beside groups with more tracks;
 * otherwise only the only matching group of a complete comparison is.
 */
export const rankLookupCandidates = (candidates: readonly LookupCandidate[], files: readonly LocalFileEvidence[],
    options: { toleranceMs?: number; searchComplete?: boolean; exactSearchComplete?: boolean; comparison?: LookupComparisonMode;
        aliases?: ReadonlyMap<string, readonly string[]>; localized?: readonly (readonly string[])[] } = {}): RankedLookup => {
    const toleranceMs = options.toleranceMs ?? METADATA_LOOKUP_LIMITS.durationToleranceMs, subsetMode = options.comparison === 'subset';
    const sorted = orderedFiles(files), distinct = distinctCandidates(candidates);
    type Scored = RankedLookupCandidate & { order: number[]; frontArtwork: boolean; release: MusicBrainzRelease | null; source: LookupCandidate['source'];
        preselectable: boolean; notChecked: boolean; audioTrackCount: number | null };
    const scored: Scored[] = distinct.map(candidate => {
        const release = usableRelease(candidate), source = candidate.source === 'itunes' ? 'itunes' as const : 'musicbrainz' as const;
        const preselectable = source !== 'itunes' || candidate.itunesCheck === 'noRelease' || candidate.itunesCheck === 'unavailable';
        const notChecked = source === 'itunes' && candidate.itunesCheck === 'unavailable';
        if (!release) return { key: candidate.key, releaseId: candidate.releaseId, status: 'incomplete', comparison: null, proposal: null,
            groupKey: null, artistMismatch: null, order: [], frontArtwork: false, release: null, source, preselectable, notChecked, audioTrackCount: null };
        if (subsetMode) {
            const { comparison, status, order, audioCount, group } = compareSubset(release, sorted, toleranceMs);
            const proposal = proposalForRelease(release);
            return { key: candidate.key, releaseId: candidate.releaseId, status, comparison, proposal,
                groupKey: status === 'matching' ? subsetGroupKeyFor(proposal, source, group) : null, artistMismatch: artistMismatchFor(release, files, options.aliases, options.localized),
                order, frontArtwork: release.frontArtwork === true, release, source, preselectable, notChecked, audioTrackCount: audioCount };
        }
        const { comparison, status, order } = compareRelease(release, sorted, toleranceMs);
        const proposal = proposalForRelease(release);
        return { key: candidate.key, releaseId: candidate.releaseId, status, comparison, proposal,
            groupKey: status === 'matching' ? groupKeyFor(proposal, source) : null, artistMismatch: artistMismatchFor(release, files, options.aliases, options.localized),
            order, frontArtwork: release.frontArtwork === true, release, source, preselectable, notChecked, audioTrackCount: null };
    });

    const byRepresentative = (left: Scored, right: Scored) => Number(right.frontArtwork) - Number(left.frontArtwork) || byText(left.releaseId, right.releaseId) || byText(left.key, right.key);
    const members = new Map<string, Scored[]>();
    for (const candidate of scored) if (candidate.groupKey) members.set(candidate.groupKey, [...(members.get(candidate.groupKey) ?? []), candidate]);
    const groups = [...members.entries()].map(([groupKey, list]) => {
        const ordered = [...list].sort(byRepresentative);
        return { groupKey, representative: ordered[0], members: ordered };
    }).sort((left, right) => byText(left.representative.key, right.representative.key));

    const others = scored.filter(candidate => candidate.status === 'notMatching' || candidate.status === 'unverified').sort((left, right) =>
        left.order[0] - right.order[0] || left.order[1] - right.order[1] || left.order[2] - right.order[2]
        || byText(left.releaseId, right.releaseId) || byText(left.key, right.key));
    const incomplete = scored.filter(candidate => candidate.status === 'incomplete').sort((left, right) => byText(left.key, right.key));
    const strip = ({ order: _order, frontArtwork: _frontArtwork, release: _release, source: _source, preselectable: _preselectable, notChecked: _notChecked,
        audioTrackCount: _audioTrackCount, ...candidate }: Scored): RankedLookupCandidate => candidate;
    const ranked = [...groups.flatMap(group => group.members), ...others, ...incomplete].map(strip);

    const matching = scored.filter(candidate => candidate.status === 'matching');
    const select = (candidate: Scored, basis: LookupPreselection['basis']): LookupPreselection => ({ candidateKey: candidate.key, groupKey: candidate.groupKey!, basis,
        artistMismatch: candidate.artistMismatch === true, ...(candidate.notChecked ? { notChecked: true } : {}) });
    let preselection: LookupPreselection | null = null;
    const identifierRules: [LookupPreselection['basis'], string | null, (candidate: Scored, value: string) => boolean][] = [
        ['releaseId', sharedIdentifier(files, file => normalizeMusicBrainzId(file.identifiers.releaseId)),
            (candidate, value) => normalizeMusicBrainzId(candidate.releaseId) === value],
        ['barcode', sharedIdentifier(files, file => normalizeGtin(file.identifiers.barcode)?.gtin14 ?? null),
            (candidate, value) => normalizeGtin(candidate.release?.barcode ?? null)?.gtin14 === value],
        ['catalogNumber', sharedIdentifier(files, file => typeof file.identifiers.catalogNumber === 'string' && folded(file.identifiers.catalogNumber) ? folded(file.identifiers.catalogNumber) : null),
            (candidate, value) => (candidate.release?.labels ?? []).some(label => label.catalogNumber !== null && folded(label.catalogNumber) === value)]
    ];
    for (const [basis, value, matches] of identifierRules) {
        if (!value) continue;
        const hits = matching.filter(candidate => matches(candidate, value));
        // A lone hit that may not be preselected (an iTunes-only candidate not yet ruled out in MusicBrainz) preselects nothing.
        if (hits.length === 1) { if (hits[0].preselectable) preselection = select(hits[0], basis); break; }
    }
    // Subset mode counts audio tracks: an incomplete candidate hides an exact-count group only when it could have exactly as many,
    // and one known to have no audio track (a count of 0) hides nothing.
    const hidden = subsetMode ? distinct.filter(candidate => !usableRelease(candidate) && candidate.missing !== true).map(lookupAudioTrackCount) : [];
    const completeness = subsetMode ? {
        exact: (options.exactSearchComplete ?? options.searchComplete) !== false && !hidden.some(count => count !== 0 && lookupTrackCountPlausible(count, files.length)),
        subset: options.searchComplete !== false && !hidden.some(count => lookupSubsetTrackCountPlausible(count, files.length))
    } : null;
    const partialComparison = completeness ? !completeness.subset : options.searchComplete === false || distinct.some(candidate => !usableRelease(candidate) && candidate.missing !== true
        && lookupTrackCountPlausible(candidate.summary?.trackCount ?? candidate.reportedTrackCount, files.length));
    const exactGroups = completeness?.exact ? groups.filter(group => group.representative.audioTrackCount === files.length) : [];
    if (!preselection && exactGroups.length === 1 && exactGroups[0].representative.preselectable) preselection = select(exactGroups[0].representative, 'exactTrackCount');
    if (!preselection && groups.length === 1 && !partialComparison && groups[0].representative.preselectable) preselection = select(groups[0].representative, 'onlyMatchingGroup');

    return {
        candidates: ranked,
        groups: groups.map(group => ({ groupKey: group.groupKey, representativeKey: group.representative.key,
            memberKeys: group.members.map(member => member.key), proposal: group.representative.proposal! })),
        preselection,
        disclosure: {
            // Subset mode counts unknown durations as its comparisons do; the exact count is unchanged for imports.
            unknownLocalDurations: files.filter(file => (subsetMode ? lookupDurationMs(file.durationMs) : file.durationMs) === null).length,
            unknownLocalDiscNumbers: files.filter(file => file.discNumber === null).length,
            partialComparison
        },
        ...(completeness ? { completeness } : {})
    };
};
